module.exports = function(RED) {
    function BranchResponseNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', function(msg) {
            const response = msg.payload || msg.dtmfDigits;
            
            // Simple routing - first output for match 1, second for 2, etc.
            if (response === "1") node.send([msg, null, null]);
            else if (response === "2") node.send([null, msg, null]);
            else node.send([null, null, msg]); // default / invalid
        });
    }
    RED.nodes.registerType("branch-response", BranchResponseNode);
};